// Writes src/api/bindings/index.ts re-exporting every type generated by ts-rs.
// Run via `npm run bindings` (after `cargo test` has exported the .ts files).
import { readdirSync, writeFileSync } from "node:fs";

const dir = new URL("../src/api/bindings/", import.meta.url);
const files = readdirSync(dir)
  .filter((f) => f.endsWith(".ts") && f !== "index.ts")
  .sort();
const body =
  "// Generated by scripts/gen-bindings-index.mjs — do not edit.\n" +
  files.map((f) => `export type * from "./${f.replace(/\.ts$/, "")}";`).join("\n") +
  "\n";
writeFileSync(new URL("index.ts", dir), body);
console.log(`bindings index: ${files.length} types`);
